ALTER TABLE vendor_businesses ADD COLUMN public_visible boolean NOT NULL DEFAULT false;
CREATE TABLE vendor_discovery_profiles(business_id uuid PRIMARY KEY REFERENCES vendor_businesses(id) ON DELETE CASCADE,verified boolean NOT NULL DEFAULT false,verification_scope text[] NOT NULL DEFAULT '{}',average_rating decimal(3,2) NOT NULL DEFAULT 0 CHECK(average_rating BETWEEN 0 AND 5),review_count integer NOT NULL DEFAULT 0 CHECK(review_count>=0),traditions text[] NOT NULL DEFAULT '{}',styles text[] NOT NULL DEFAULT '{}',response_rate integer NOT NULL DEFAULT 0 CHECK(response_rate BETWEEN 0 AND 100),response_minutes integer,last_active_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendor_category_field_values(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES vendor_businesses(id) ON DELETE CASCADE,category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,field_key varchar(80) NOT NULL,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,category_id,field_key));
CREATE INDEX vendor_category_field_values_category_key_idx ON vendor_category_field_values(category_id,field_key); CREATE INDEX vendor_category_field_values_value_gin_idx ON vendor_category_field_values USING gin(value);
CREATE TABLE vendor_sponsored_placements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES vendor_businesses(id) ON DELETE CASCADE,city_id uuid NOT NULL REFERENCES locations(id) ON DELETE RESTRICT,category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,daily_impression_cap integer NOT NULL DEFAULT 500 CHECK(daily_impression_cap>0),impressions_today integer NOT NULL DEFAULT 0 CHECK(impressions_today>=0),impression_date date NOT NULL DEFAULT current_date,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE INDEX vendor_sponsored_placements_lookup_idx ON vendor_sponsored_placements(city_id,category_id,active,starts_at,ends_at);
CREATE INDEX vendor_businesses_public_search_idx ON vendor_businesses(status,public_visible,base_city_id) WHERE status='APPROVED' AND public_visible;
CREATE INDEX vendor_businesses_name_trgm_idx ON vendor_businesses USING gin(name gin_trgm_ops); CREATE INDEX vendor_businesses_languages_gin_idx ON vendor_businesses USING gin(languages);
CREATE INDEX vendor_discovery_traditions_gin_idx ON vendor_discovery_profiles USING gin(traditions); CREATE INDEX vendor_discovery_styles_gin_idx ON vendor_discovery_profiles USING gin(styles);
CREATE INDEX vendor_services_search_price_idx ON vendor_services(business_id,category_id,price) WHERE active;
ALTER TABLE vendor_discovery_profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE vendor_category_field_values ENABLE ROW LEVEL SECURITY; ALTER TABLE vendor_sponsored_placements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON vendor_discovery_profiles,vendor_category_field_values,vendor_sponsored_placements FROM anon,authenticated;
INSERT INTO permissions(code,description) VALUES ('sponsored.manage','Manage clearly labelled sponsored discovery placements') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' AND p.code='sponsored.manage' ON CONFLICT DO NOTHING;
